head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods70205";
scwin.pageSize = null;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — DST_URL

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_disclsTitle", fn: function () { return String((dma_pageContext.get("disclsTitle") ?? "")); } },
        { childId: "__rb0", fn: function () { return "전체 " + String(dma_docPage.get("total")) + "건 [" + String(dma_docPage.get("currentPage")) + "/" + String(dma_docPage.get("endListPage")) + " 페이지]"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent("ipt_pageIndex").setValue("1");
};

// [A] 초기 목록 미해결 — jldods70205: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.pageSize = "" + dma_pageContext.get("pageSize") + "";
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods70205.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_disclsTitle_onkeyup
 * @description ipt_disclsTitle 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_disclsTitle_onkeyup = async function(e){
    try {
        await scwin.enterSearchForm();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70205.ipt_disclsTitle_onkeyup' }); }
};

/**
 * @method
 * @name input_20_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.input_20_onclick = async function(e){
    try {
        await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70205.input_20_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        scwin.initPageIndex(); await scwin.searchList();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70205.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_docPageList_oncellclick
 * @description grd_docPageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_docPageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_docPageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.goViewer(r["acptNo"], r["disclsMaindocFormCd"], r["formVer"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_docPageList.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_docPageList_fmt_formKorNm
 * @description grd doc Page List fmt form Kor Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_formKorNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "disclsAcptTpCd") ?? '') : '');
        if (v === 'M') { return "[정정]"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.formKorNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name enterSearchForm
 * @description enter Search Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.enterSearchForm = async function () {
    if (event.keyCode === 13) {
        await scwin.searchList();
    }
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    const frm = (document.searchForm || { elements: [] });
    if ($c.util.getComponent('ipt_fromDate').getValue()> $c.util.getComponent('ipt_toDate').getValue()) {
        await alertE('시작일자는 종료일자 이전 이어야 합니다.');
        return;
    }
    blockLoading();
    /* 수동 전환 필요: searchForm.submit() — as-is 자기제출(action 없음), 대체 tx 미정 */ await $c.win.alert("이 동작은 아직 전환되지 않았습니다(as-is 폼 «searchForm» 자기제출 — 대체 서버 호출 미정).");
};

/**
 * @method
 * @name goViewer
 * @description go Viewer 처리
 * @param {*} acptNo acptNo
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @returns {void}
 * @hidden N
 */
scwin.goViewer = function (acptNo, formCd, formVer) {
    fn_examViewer((String(((dma_pageContext.get("DST_URL") ?? "")) === null ? '' : ((dma_pageContext.get("DST_URL") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("DST_URL") ?? "")) === null ? '' : ((dma_pageContext.get("DST_URL") ?? "")))), acptNo);
};

/**
 * @method
 * @name alertE
 * @description alert E 처리
 * @param {String} msg 항목명
 * @param {*} callback callback
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }

/**
 * @method
 * @name krxpage_pagenavigator_62_onclick
 * @description krxpage_pagenavigator_62 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_62_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; await scwin.searchList(); };
